    await eventually(() => seen.filter(frame => frame.type === 'conversation_list' || frame.type === 'error').length >= 2);

    expect({
      askedFor: calls.map(call => call.userId),
      answered: seen.filter(frame => frame.type === 'conversation_list').map(frame => frame.conversations?.map(row => row.sessionId)),
