import {WebSocket} from 'ws';
import * as engine from '../index.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {fiveMemberStore} from '../infrastructure/stores/sessionStoreTestSupport.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import {validateMessage} from './ws/validation.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {deferred, startEngineWith} from './wsTestSupport.js';
import type {HalServer} from './createServer.js';
import {setLogger} from '../shared/logger.js';

// The list a browser asks over the socket it already authenticated on: real upgrades, real stores, frames as a client reads them.

interface SummaryWire {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

interface Frame {
  type: string;
  code?: string;
  message?: string;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  index?: number;
  entry?: {role: string};
  conversations?: SummaryWire[];
}

interface RecordedCall {
  userId: string | number | undefined;
  options: SessionListOptions | undefined;
}

type EngineOptions = Parameters<typeof startEngineWith>[0];

const silence = {debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined};

beforeAll(() => {
  setLogger(silence);
});

afterAll(() => {
  setLogger();
});

const engines: HalServer[] = [];
const clients: WebSocket[] = [];

// Each server sees its sockets close before it stops, so no close is logged after the logger above is restored.
afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of engines.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
});

const connect = (url: string): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  return client;
};

const record = (client: WebSocket): Frame[] => {
  const seen: Frame[] = [];
  client.on('message', raw => seen.push(JSON.parse(String(raw)) as Frame));
  return seen;
};

const send = (client: WebSocket, frame: unknown): void => client.send(JSON.stringify(frame));

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 200 && !check(); attempt += 1) await new Promise(resolve => setTimeout(resolve, 10));
};

const stamp = (offsetMs: number): string => new Date(Date.now() + offsetMs).toISOString();

const listed = (seen: Frame[]): SummaryWire[] =>
  seen.find(frame => frame.type === 'conversation_list')?.conversations ?? [];

// `history` is this ticket's option; the cast holds the file together until the round adds it to the server's options.
const start = async (options: {sessionStore: SessionStore} & Record<string, unknown>): Promise<string> => {
  const {url, hal} = await startEngineWith(options as unknown as EngineOptions);
  engines.push(hal);
  return url;
};

// Three conversations of the connecting user, last active at distinct moments, so the answer's order is decided.
const seededStore = (): InMemorySessionStore => {
  const store = new InMemorySessionStore();
  const conversation = (sessionId: string, entryCount: number, activeAt: string): void => {
    const session = store.create(sessionId, 'u1');
    for (let entry = 0; entry < entryCount; entry += 1) {
      session.entries.push({role: 'user', content: 'hello', timestamp: activeAt});
    }
  };
  conversation('s1', 2, stamp(60_000));
  conversation('s2', 1, stamp(120_000));
  conversation('s3', 3, stamp(180_000));
  return store;
};

const summary = (sessionId: string, entryCount: number): SessionSummary => ({
  sessionId,
  createdAt: new Date(0),
  updatedAt: new Date(1_000 + entryCount),
  entryCount,
});

// The shipped store underneath, with listFor instrumented: the arguments it was called with are what this reads.
const storeOver = (listFor?: SessionStore['listFor']): SessionStore => {
  const memory = new InMemorySessionStore();
  return {
    create: (sessionId, userId, options) => memory.create(sessionId, userId, options),
    get: sessionId => memory.get(sessionId),
    delete: sessionId => memory.delete(sessionId),
    count: () => memory.count(),
    clear: () => memory.clear(),
    lookup: sessionId => memory.lookup(sessionId),
    ...(listFor === undefined ? {} : {listFor}),
  };
};

const recordingStore = (
  lists: Array<[string | number, SessionSummary[]]>
): {store: SessionStore; calls: RecordedCall[]} => {
  const byUser = new Map<string | number, SessionSummary[]>(lists);
  const calls: RecordedCall[] = [];
  const store = storeOver((userId, options) => {
    calls.push({userId, options});
    return byUser.get(userId) ?? [];
  });
  return {store, calls};
};

// Streams half an answer, then holds until the test releases it, so the turn stays open while the list is asked.
const heldAnswer = (until: Promise<void>): ChatOrchestrator => ({
  processMessage: async () => 'held',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'half'};
    await until;
    yield {type: 'stop', stopReason: 'end_turn'};
  },
});

describe('the conversation list over the websocket', () => {
  it('validates a list_conversations frame by its fields alone, naming the field it refuses', () => {
    const cursor = {updatedAt: '2026-01-15T14:30:00.000Z', sessionId: 's1'};
    const refusalOf = (frame: unknown): string => {
      const result = validateMessage(frame);
      return result.valid ? 'accepted' : result.error;
    };

    const stillValid = {
      ping: validateMessage({type: 'ping', timestamp: 1}).valid,
      userMessage: validateMessage({type: 'user_message', content: 'hi'}).valid,
    };
    const bare = validateMessage({type: 'list_conversations'});
    const withFields = validateMessage({
      type: 'list_conversations',
      limit: 2,
      before: cursor,
      userId: 'u9',
      content: 'not mine',
    });

    expect({stillValid, bare, withFields: withFields.valid ? withFields.data : withFields.error}).toEqual({
      stillValid: {ping: true, userMessage: true},
      bare: {valid: true, data: {type: 'list_conversations'}},
      withFields: {type: 'list_conversations', limit: 2, before: cursor},
    });

    const refusals = {
      limitZero: refusalOf({type: 'list_conversations', limit: 0}),
      limitOver: refusalOf({type: 'list_conversations', limit: 201}),
      limitFraction: refusalOf({type: 'list_conversations', limit: 1.5}),
      limitString: refusalOf({type: 'list_conversations', limit: '10'}),
      beforeString: refusalOf({type: 'list_conversations', before: 'not a date'}),
      beforeTimeOnly: refusalOf({type: 'list_conversations', before: {updatedAt: '2026-01-15T14:30:00.000Z'}}),
      beforeIdOnly: refusalOf({type: 'list_conversations', before: {sessionId: 's1'}}),
      beforeBadTime: refusalOf({type: 'list_conversations', before: {updatedAt: 'not a date', sessionId: 's1'}}),
    };
    const limits = [refusals.limitZero, refusals.limitOver, refusals.limitFraction, refusals.limitString];
    const befores = [refusals.beforeString, refusals.beforeTimeOnly, refusals.beforeIdOnly, refusals.beforeBadTime];

    expect({
      inBounds: {
        one: validateMessage({type: 'list_conversations', limit: 1}).valid,
        twoHundred: validateMessage({type: 'list_conversations', limit: 200}).valid,
      },
      refused: [...limits, ...befores].every(message => message !== 'accepted'),
      limitsNamed: limits.every(message => message.includes('limit')),
      beforesNamed: befores.every(message => message.includes('before')),
    }).toEqual({
      inBounds: {one: true, twoHundred: true},
      refused: true,
      limitsNamed: true,
      beforesNamed: true,
    });
  });

  it('answers exactly one conversation_list, newest first, with ISO times and no stream_end', async () => {
    const url = await start({sessionStore: seededStore(), history: {enabled: true}});
    const client = connect(url);
    const seen = record(client);
    await eventually(() => seen.some(frame => frame.type === 'connected'));

    send(client, {type: 'list_conversations'});
    await eventually(() => seen.some(frame => frame.type === 'conversation_list' || frame.type === 'error'));

    const own = seen.find(frame => frame.type === 'connected')?.sessionId ?? '';
    const rows = listed(seen);
    expect({types: seen.map(frame => frame.type), rows: rows.map(row => [row.sessionId, row.entryCount])}).toEqual({
      types: ['connected', 'conversation_list'],
      rows: [
        ['s3', 3],
        ['s2', 1],
        ['s1', 2],
        [own, 0],
      ],
    });
    expect({
      isoTimes: rows.every(
        row =>
          row.createdAt === new Date(row.createdAt).toISOString() &&
          row.updatedAt === new Date(row.updatedAt).toISOString()
      ),
    }).toEqual({isoTimes: true});
  });

  it('lists the conversations of the user the socket authenticated, with the arguments the frame sent', async () => {
    const iso = stamp(0);
    const {store, calls} = recordingStore([
      ['u1', [summary('u1s1', 1)]],
      ['u9', [summary('u9s1', 2), summary('u9s2', 3)]],
    ]);
    const url = await start({sessionStore: store, history: {enabled: true}});
    const client = connect(url);
    const seen = record(client);
    await eventually(() => seen.some(frame => frame.type === 'connected'));

    send(client, {type: 'list_conversations', userId: 'u9'});
    await eventually(
      () => seen.filter(frame => frame.type === 'conversation_list' || frame.type === 'error').length >= 1
    );
    send(client, {type: 'list_conversations', limit: 2, before: {updatedAt: iso, sessionId: 's1'}});
    await eventually(
      () => seen.filter(frame => frame.type === 'conversation_list' || frame.type === 'error').length >= 2
    );

    expect({
      askedFor: calls.map(call => call.userId),
      answered: seen
        .filter(frame => frame.type === 'conversation_list')
        .map(frame => frame.conversations?.map(row => row.sessionId)),
      errors: seen.filter(frame => frame.type === 'error').map(frame => frame.code),
    }).toEqual({
      askedFor: ['u1', 'u1'],
      answered: [['u1s1'], ['u1s1']],
      errors: [],
    });
    expect(calls[1]?.options).toEqual({limit: 2, before: {updatedAt: iso, sessionId: 's1'}});
    expect({limit: calls[0]?.options?.limit, before: calls[0]?.options?.before}).toEqual({
      limit: undefined,
      before: undefined,
    });
  });

  it('answers a list it cannot give with UNSUPPORTED, never an empty one', async () => {
    const offUrl = await start({sessionStore: seededStore()});
    const off = connect(offUrl);
    const offSeen = record(off);
    await eventually(() => offSeen.some(frame => frame.type === 'connected'));
    send(off, {type: 'list_conversations'});
    await eventually(() => offSeen.some(frame => frame.type === 'error' || frame.type === 'conversation_list'));

    const withoutList = connect(await start({sessionStore: fiveMemberStore, history: {enabled: true}}));
    const withoutSeen = record(withoutList);
    await eventually(() => withoutSeen.some(frame => frame.type === 'connected'));
    send(withoutList, {type: 'list_conversations'});
    await eventually(() => withoutSeen.some(frame => frame.type === 'error' || frame.type === 'conversation_list'));

    expect({
      offTypes: offSeen.map(frame => frame.type),
      offCode: offSeen.find(frame => frame.type === 'error')?.code,
      withoutTypes: withoutSeen.map(frame => frame.type),
      withoutCode: withoutSeen.find(frame => frame.type === 'error')?.code,
      lists: [listed(offSeen).length, listed(withoutSeen).length],
    }).toEqual({
      offTypes: ['connected', 'error'],
      offCode: 'UNSUPPORTED',
      withoutTypes: ['connected', 'error'],
      withoutCode: 'UNSUPPORTED',
      lists: [0, 0],
    });
  });

  it('answers a failing store with SERVER_ERROR and stays open, and one that cannot list with UNSUPPORTED', async () => {
    const detail = 'mongo driver failed: no replica reachable';
    const failing = connect(
      await start({sessionStore: storeOver(() => Promise.reject(new Error(detail))), history: {enabled: true}})
    );
    const failingSeen = record(failing);
    await eventually(() => failingSeen.some(frame => frame.type === 'connected'));
    send(failing, {type: 'list_conversations'});
    await eventually(() => failingSeen.some(frame => frame.type === 'error'));
    send(failing, {type: 'ping', timestamp: 1234});
    await eventually(() => failingSeen.some(frame => frame.type === 'pong'));

    expect({
      types: failingSeen.map(frame => frame.type),
      code: failingSeen.find(frame => frame.type === 'error')?.code,
      leaked: failingSeen.some(frame => typeof frame.message === 'string' && frame.message.includes(detail)),
    }).toEqual({types: ['connected', 'error', 'pong'], code: 'SERVER_ERROR', leaked: false});

    // The new public error type, read off the package surface: its absence is what makes this half red.
    const StoreCannotList = (engine as unknown as Record<string, unknown>).StoreCannotList as new (
      message: string
    ) => Error;
    expect({exported: typeof StoreCannotList}).toEqual({exported: 'function'});

    const misconfigured = connect(
      await start({
        sessionStore: storeOver(() => {
          throw new StoreCannotList('this store cannot list conversations');
        }),
        history: {enabled: true},
      })
    );
    const misconfiguredSeen = record(misconfigured);
    await eventually(() => misconfiguredSeen.some(frame => frame.type === 'connected'));
    send(misconfigured, {type: 'list_conversations'});
    await eventually(() => misconfiguredSeen.some(frame => frame.type === 'error'));

    expect({
      types: misconfiguredSeen.map(frame => frame.type),
      code: misconfiguredSeen.find(frame => frame.type === 'error')?.code,
    }).toEqual({types: ['connected', 'error'], code: 'UNSUPPORTED'});
  });

  it('answers a history request beside a streaming turn, before it ends', async () => {
    const gate = deferred();
    const url = await start({
      sessionStore: seededStore(),
      history: {enabled: true},
      orchestrator: heldAnswer(gate.until),
    });
    const client = connect(url);
    const seen = record(client);
    await eventually(() => seen.some(frame => frame.type === 'connected'));

    send(client, {type: 'user_message', content: 'hello'});
    await eventually(() => seen.some(frame => frame.type === 'entry_delta'));
    send(client, {type: 'list_conversations'});
    await eventually(() => seen.some(frame => frame.type === 'conversation_list' || frame.type === 'error'));
    gate.release();
    await eventually(() => seen.some(frame => frame.type === 'stream_end'));

    const types = seen.map(frame => frame.type);
    expect({
      lists: types.filter(type => type === 'conversation_list'),
      beforeTurnEnd: types.indexOf('conversation_list') < types.indexOf('stream_end'),
      errors: types.filter(type => type === 'error'),
    }).toEqual({lists: ['conversation_list'], beforeTurnEnd: true, errors: []});
  });

  it('hands a client a conversation it can reopen by reconnecting with its id', async () => {
    const url = await start({sessionStore: seededStore(), history: {enabled: true}, resume: {enabled: true}});
    const first = connect(url);
    const firstSeen = record(first);
    await eventually(() => firstSeen.some(frame => frame.type === 'connected'));
    send(first, {type: 'list_conversations'});
    await eventually(() => firstSeen.some(frame => frame.type === 'conversation_list' || frame.type === 'error'));

    const reopened = listed(firstSeen)[0]?.sessionId ?? '';
    expect({picked: reopened, from: listed(firstSeen).map(row => row.sessionId)}).toEqual({
      picked: 's3',
      from: ['s3', 's2', 's1', expect.any(String)],
    });

    const second = connect(`${url}?sessionId=${reopened}`);
    const secondSeen = record(second);
    await eventually(() => secondSeen.filter(frame => frame.type === 'entry_upsert').length >= 3);

    expect(secondSeen[0]).toMatchObject({type: 'connected', resumed: true, entryCount: 3, sessionId: 's3'});
    expect(secondSeen.slice(1).map(frame => [frame.index, frame.entry?.role])).toEqual([
      [0, 'user'],
      [1, 'user'],
      [2, 'user'],
    ]);
  });
});

